        var list=Field<ItemList>(o,"list");list.SizeFlagsVertical=Control.SizeFlags.ExpandFill;list.AllowReselect=true;list.FixedColumnWidth=0;list.MaxColumns=1;list.MaxTextLines=1;o.AddChild(list);list.ItemSelected+=index=>selected(o,(int)index);list.ItemActivated+=_=>{if(can_use_current(o))o.EmitSignal("preview_requested",o.Get("current"));};var row=new HBoxContainer();o.AddChild(row);var preview=Field<Button>(o,"_preview_button");preview.Text="\u25b6";preview.TooltipText="Preview selected sound";row.AddChild(preview);preview.Pressed+=()=>{if(can_use_current(o))o.EmitSignal("preview_requested",o.Get("current"));};var add=Field<Button>(o,"_add_button");add.Text="+ Add";row.AddChild(add);add.Pressed+=()=>{if(can_use_current(o))o.EmitSignal("add_requested",o.Get("current"));};var favorite=new Button{Text="\u2606",TooltipText="Toggle favorite"};row.AddChild(favorite);favorite.Pressed+=()=>toggle_favorite(o);
