    public void build_preset_filters(Control o)
    {
        var kind=Field<OptionButton>(o,"_preset_kind_filter");kind.FitToLongestItem=false;kind.ClipText=true;kind.AddItem("All preset kinds");kind.SetItemMetadata(0,"");foreach(string id in new[]{"generator","effects","instrument","pattern","composition","bundle"}){kind.AddItem("Preset: "+id.Capitalize());kind.SetItemMetadata(kind.ItemCount-1,id);}kind.TooltipText="A specific kind shows saved presets only. Combines with category, tags and search.";var filters=Field<Control>(o,"_filters");filters.AddChild(kind);kind.ItemSelected+=_=>refresh(o);var tags=Field<OptionButton>(o,"_tag_filter");tags.FitToLongestItem=false;tags.ClipText=true;filters.AddChild(tags);tags.ItemSelected+=_=>refresh(o);update_tag_filter(o);var clear=new Button{Text="Clear filters",TooltipText="Reset search, category, preset kind and tag filters. Favorites and recent history are kept."};filters.AddChild(clear);clear.Pressed+=()=>clear_filters(o);
    }
    public void clear_filters(Control o){Field<OptionButton>(o,"category").Select(0);Field<OptionButton>(o,"_preset_kind_filter").Select(0);Field<OptionButton>(o,"_tag_filter").Select(0);Field<LineEdit>(o,"search").Text="";refresh(o);}
    public void update_tag_filter(Control o)
    {
        var control=Field<OptionButton>(o,"_tag_filter");string previous=control.Selected>=0?control.GetSelectedMetadata().AsString():"";var known=new SortedDictionary<string,string>(StringComparer.Ordinal);foreach(var raw in Items(o,"entries")){var entry=raw.AsGodotDictionary();if(S(entry,"kind")!="preset")continue;foreach(string tag in Strings(Get(entry,"tags",Array.Empty<string>()))){string key=tag.ToLowerInvariant();if(!known.ContainsKey(key))known[key]=tag;}}control.Clear();control.AddItem("All tags");control.SetItemMetadata(0,"");control.AddItem("Untagged presets");control.SetItemMetadata(1,"untagged");string active=previous.StartsWith("tag:")?previous[4..]:"";int limit=128-(active.Length>0?1:0);var shown=new List<string>();foreach(string key in known.Keys){if(key==active)continue;if(shown.Count>=limit)break;shown.Add(key);}if(active.Length>0)shown.Add(active);shown.Sort(StringComparer.Ordinal);foreach(string key in shown){string label=known.TryGetValue(key,out var value)?value:key;control.AddItem("Tag: "+label[..Math.Min(label.Length,64)]+(label.Length>64?"\u2026":""));int index=control.ItemCount-1;control.SetItemMetadata(index,"tag:"+key);control.GetPopup().SetItemTooltip(index,"Exact tag: "+label);}control.Select(0);for(int i=0;i<control.ItemCount;i++)if(control.GetItemMetadata(i).AsString()==previous){control.Select(i);break;}control.TooltipText="Tag filters show saved presets only and match whole tags, ignoring case. Search covers every tag.";if(known.Count>128)control.TooltipText+=" Menu limited to 128 tags; search finds the rest.";
    }
