0,000 entries, 15 seconds and 16 MiB header reads per scan. Audio is loaded only for preview/add.";folders.AddChild(status);var picker=Field<FileDialog>(o,"_folder_dialog");picker.Access=FileDialog.AccessEnum.Resources;picker.FileMode=FileDialog.FileModeEnum.OpenDir;picker.CurrentDir="res://";picker.Title="Index a project audio folder";o.AddChild(picker);picker.DirSelected+=value=>add_source(o,value);
    }
    public void add_source(Control o,string value)
    {
        using var index=new AudioAssetIndexOperations();string root=index.canonical_root(value);var status=Field<Label>(o,"_scan_status");if(root.Length==0||index.path_state(root,true)!="available"){status.Text="Choose a readable res:// folder without links or excluded directories.";return;}var roots=Items(o,"_project_roots");foreach(var raw in roots)if(index.contains_path(raw.AsString(),root)){status.Text="That folder is already included. Refresh to scan it again.";return;}var next=new GArray();foreach(var raw in roots)if(!index.contains_path(root,raw.AsString()))next.Add(raw);if(next.Count>=8){status.Text="Up to eight project folders can be indexed. Remove one first.";return;}next.Add(root);Assign(roots,next);update_sources(o);start_scan(o);save(o,"project_index","");
    }
    public void remove_source(Control o)
    {
        int position=Field<OptionButton>(o,"_source_menu").Selected;var roots=Items(o,"_project_roots");if(position<0||position>=roots.Count)return;roots.RemoveAt(position);Field<Node>(o,"_index").Call("cancel");o.Set("_index_generation",-1);var kept=new GArray();using var index=new AudioAssetIndexOperations();foreach(var raw in Items(o,"_project_entries")){var entry=raw.AsGodotDictionary();foreach(var root in roots)if(index.contains_path(root.AsString(),S(entry,"source"))){kept.Add(entry);break;}}Assign(Items(o,"_project_entries"),kept);update_sources(o);reload(o);if(roots.Count==0){Field<Button>(o,"_cancel_button").Disabled=true;Field<Label>(o,"_scan_status").Text="No project folders selected. Imported files and favorites are kept.";}else start_scan(o);save(o,"project_index","");
    }
    public void update_sources(Control o){var menu=Field<OptionButton>(o,"_source_menu");menu.Clear();var roots=Items(o,"_project_roots");foreach(var root in roots){menu.AddItem(root.AsString());menu.GetPopup().SetItemTooltip(menu.ItemCount-1,root.AsString());}menu.Disabled=roots.Count==0;Field<Button>(o,"_remove_button").Disabled=roots.Count==0;Field<Button>(o,"_refresh_button").Disabled=roots.Count==0;}
    public void start_scan(Control o){var roots=Items(o,"_project_roots");if(roots.Count==0)return;o.Set("_index_generation",Field<Node>(o,"_index").Call("request",roots,o.Get("_project_entries")));Field<Button>(o,"_cancel_button").Disabled=false;Field<Label>(o,"_scan_status").Text="Scanning project audio headers\u2026";}
    public void cancel_scan(Control o){Field<Node>(o,"_index").Call("cancel");o.Set("_index_generation",-1);Field<Button>(o,"_cancel_button").Disabled=true;Field<Label>(o,"_scan_status").Text="Indexing stopped. Previous results are kept.";}
